import http.server as h, functools as f
class H(h.SimpleHTTPRequestHandler):
    def end_headers(s):
        s.send_header('Cross-Origin-Opener-Policy', 'same-origin'); s.send_header('Cross-Origin-Embedder-Policy', 'require-corp'); super().end_headers()
h.ThreadingHTTPServer(('', 8767), f.partial(H, directory='build-site')).serve_forever()
